window.MGProseData("97f9fadea08e792e8ddf58ad369ce24a09b985380da3c0b042d8f75e8e4c12fb",{"html":"\u003cp>\u003cstrong>S1．结论成立，且不需要纤维下确界取到。\u003c/strong>\u003c/p>\n\u003cp>显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_0\\in E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x_0)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_F(q_Fx_0)\\le f(x_0)\u0026lt;\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>为证明凸性，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(y_i,t_i)\\in\\operatorname{epi}_{\\mathbb R}(g_F)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i=1,2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_Fx_i=y_i,\\qquad f(x_i)\u0026lt;t_i+\\varepsilon.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的凸性，对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;\\lambda\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_F(\\lambda y_1+(1-\\lambda)y_2)\n\\le f(\\lambda x_1+(1-\\lambda)x_2)\n\\le\\lambda t_1+(1-\\lambda)t_2+\\varepsilon.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>↓\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\\downarrow0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即得实高度上图的凸性。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>⊂\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\subset K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F=r_{KF}q_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而有纤维分解\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⋃\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>K\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{x:q_Fx=y\\}\n=\\bigcup_{\\substack{z\\in K^*\\\\r_{KF}z=y}}\\{x:q_Kx=z\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对集合并逐次取下确界，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{g_F(y)=\\inf_{r_{KF}z=y}g_K(z).}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些论证均只使用下确界的定义，不要求下确界取到。\u003c/p>\n\u003cp>\u003cstrong>S2．各 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续，有限值处的纤维下确界取到。\u003c/strong>\u003c/p>\n\u003cp>选取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的一组基，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的坐标就是有限多个连续线性泛函，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>E\u003c/mi>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F:E\\to F^*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续。\u003c/p>\n\u003cp>固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y)=\\alpha\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nB_n=\\{x:q_Fx=y,\\ f(x)\\le\\alpha+1/n\\},\\qquad n\\ge1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由下确界定义，每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续、纤维闭，这些集合是紧集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>α\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{f\\le\\alpha+1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的闭集，且递减。因此由紧性，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bigcap_{n\\ge1}B_n\\ne\\varnothing.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n任取其中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，便有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_Fx=y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)\\le\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。结合下确界定义，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)=\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>于是，对每个有限实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{y:g_F(y)\\le c\\}=q_F(\\{x:f(x)\\le c\\}).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右侧是紧集的连续像；有限维空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F^*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Hausdorff 空间，故该像闭。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的所有有限实数次水平集均闭，等价地，其实高度上图闭。\u003c/p>\n\u003cp>\u003cstrong>S3．所求 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 存在且唯一。\u003c/strong>\u003c/p>\n\u003cp>记紧集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c=\\{x:f(x)\\le c\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_F=C_c\\cap q_F^{-1}(\\{y_F\\}).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y_F)\\le c\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 S2 的取到结论，每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空；它也是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的闭集。\u003c/p>\n\u003cp>对有限多个观测空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_1,\\ldots,F_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=F_1+\\cdots+F_m.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n兼容性给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>⊆\u003c/mo>\u003cmunderover>\u003cmo>⋂\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>m\u003c/mi>\u003c/munderover>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_K\\subseteq\\bigcap_{i=1}^m A_{F_i}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(A_F)_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 具有有限交性质。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的紧性，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmi>F\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bigcap_F A_F\\ne\\varnothing.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取交集中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即有全部所需记录及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)\\le c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x,x\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都实现这些记录，对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi\\in E\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\operatorname{span}\\{\\varphi\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varphi(x)=\\varphi(x\u0026#x27;).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Hausdorff 局部凸空间，Hahn–Banach 定理保证 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分离点，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x=x\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此上述交集恰为单点，给出了所求构造。\u003c/p>\n\u003cp>\u003cstrong>S4．成立；无需 S2 的附加条件。\u003c/strong>\u003c/p>\n\u003cp>先说明闭上图恢复的一般事实。对非负凸函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_u=\\overline{\\operatorname{epi}_{\\mathbb R}(u)}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它是闭凸集，向上封闭，且包含于“高度非负”的半空间。故每个垂直截面为空集或某个闭射线 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[a,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此存在非负下半连续凸函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(\\bar u)=C_u.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n具体地，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmo>:\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar u(v)=\\inf\\{t\\in\\mathbb R:(v,t)\\in C_u\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n空截面时取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>上图包含关系给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>≤\u003c/mo>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar u\\le u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\\le u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续、凸，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(u)\n\\subseteq\\operatorname{epi}_{\\mathbb R}(h),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而后者闭，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_u\\subseteq\\operatorname{epi}_{\\mathbb R}(h),\n\\qquad h\\le\\bar u.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这一论证也适用于同时允许取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">-\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>现在仅用记录 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构造\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>⊂\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>F\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{G(x)=\\sup_{\\substack{F\\subset E\u0026#x27;\\\\ \\dim F\u0026lt;\\infty}}\n                 \\bar g_F(q_Fx).}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n各项均非负、下半连续、凸，故其上确界也具有这些性质。并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(q_Fx)\\le g_F(q_Fx)\\le f(x),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\\le f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G(x_0)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>扩大观测空间时，由 S1，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(r_{KF}z)\\le g_F(r_{KF}z)\\le g_K(z).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>∘\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\\circ r_{KF}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续且凸，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r_{KF}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续线性。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最大性，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\bar g_F(r_{KF}z)\\le\\bar g_K(z).}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(q_Fx)\\le\\bar g_K(q_Kx).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些拉回到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的函数随观测空间扩大而单调上升，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是它们的有向上确界。\u003c/p>\n\u003cp>下面证明关键等式\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\operatorname{epi}_{\\mathbb R}(G)\n       =\\overline{\\operatorname{epi}_{\\mathbb R}(f)}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_F(x,t)=(q_Fx,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。首先，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\overline{P_F(\\operatorname{epi}_{\\mathbb R}(f))}\n=\\overline{\\operatorname{epi}_{\\mathbb R}(g_F)}\n=\\operatorname{epi}_{\\mathbb R}(\\bar g_F). \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n事实上，投影上图包含于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的上图；反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y)\\le t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_Fx=y,\\qquad f(x)\u0026lt;t+\\varepsilon,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(y,t+\\varepsilon)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 属于投影上图，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>↓\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\\downarrow0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即得另一方向的闭包包含。\u003c/p>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\\le f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续，已有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\\subseteq\\operatorname{epi}_{\\mathbb R}(G)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(x,t)\\notin C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 Hausdorff 局部凸空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E\\times\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的非空闭凸集，可以应用点与闭凸集的严格分离定理。存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi\\in E\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a,\\beta\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi>s\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varphi(x)+at\u0026lt;\\beta\n\\le\\varphi(w)+as\\qquad((w,s)\\in C).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\operatorname{span}\\{\\varphi\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，允许 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\{0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。投影上图包含于闭半空间\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>a\u003c/mi>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>β\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{(y,s):y(\\varphi)+as\\ge\\beta\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 (1)，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{epi}_{\\mathbb R}(\\bar g_F)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也包含于该半空间，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(q_Fx,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不在其中。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>t\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(q_Fx)\u0026gt;t,\\qquad G(x)\u0026gt;t.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这证明了所需上图等式，即 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmi>f\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G=\\bar f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>最后，任何题设允许的竞争函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(G)\n=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}\n\\subseteq\\operatorname{epi}_{\\mathbb R}(h),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\\le G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这里没有对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的无穷值另作限制。\u003c/p>\n\u003cp>\u003cstrong>S5．不成立。\u003c/strong>\u003c/p>\n\u003cp>在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb R^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>b\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>b\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC=\\{(a,b):a\\ge0,\\ b\\ge0,\\ ab\\ge1\\}\n =\\{(a,b):a\u0026gt;0,\\ b\\ge1/a\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(a,b)=\n\\begin{cases}\n0,\u0026amp;(a,b)\\in C,\\\\\n+\\infty,\u0026amp;(a,b)\\notin C.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n第一个表达式说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 闭；第二个表达式及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>↦\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\mapsto1/a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的凸性说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 凸。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(f)=C\\times[0,\\infty)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n闭且凸，而且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(1,1)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\operatorname{span}\\{\\varphi\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi(a,b)=a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F^*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 识别为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_F(a)=\n\\begin{cases}\n0,\u0026amp;a\u0026gt;0,\\\\\n+\\infty,\u0026amp;a\\le0.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(1/n)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，但 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(0)=+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不下半连续。\u003c/p>\n\u003cp>\u003cstrong>S6．所述等价与恒等式成立，但最外层下半连续化不能总省去。\u003c/strong>\u003c/p>\n\u003cp>由 S4，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G=f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 蕴含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续。反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续，则共同设定中的凸性使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 本身成为合法竞争函数，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf\\le G\\le f.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmo>⟺\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>f\u003c/mi>\u003cmtext> 下半连续\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{G=f\\quad\\Longleftrightarrow\\quad f\\text{ 下半连续}.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>⊂\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\subset K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nv(y)=\\inf_{r_{KF}z=y}\\bar g_K(z).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由与 S1 相同的近似下确界论证，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非负、凸且至少一点有限。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K\\le g_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 S1，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nv\\le g_F.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，S4 的扩大观测空间关系给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(r_{KF}z)\\le\\bar g_K(z),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对纤维取下确界，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F\\le v\\le g_F.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续、凸，左不等式及最大性给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmover accent=\"true\">\u003cmi>v\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\\le\\bar v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；右不等式及最大性给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>v\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar v\\le\\bar g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo>⟼\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\bar g_F\n=\\overline{\\left(y\\longmapsto\n       \\inf_{r_{KF}z=y}\\bar g_K(z)\\right)}.\n}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>最外层的横线不能总省去。使用 S5 的例子，并取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K=E\u0026#x27;=(\\mathbb R^2)\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在自然识别下，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_K=f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K=f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\inf_{r_{KF}z=a}\\bar g_K(z)=g_F(a),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(a)=\n\\begin{cases}\n0,\u0026amp;a\\ge0,\\\\\n+\\infty,\u0026amp;a\u0026lt;0.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 处，左侧 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F(0)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，未经最外层下半连续化的右侧为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故不能省去。\u003c/p>\n","source":"assets/content/97f9fadea08e792e8ddf58ad369ce24a09b985380da3c0b042d8f75e8e4c12fb.html"});
